183	        Claim claim = claims.findForUpdate(id, sheetId)
184	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
185	        refuseIfClosed(sheetId, claim.getDate());
186	        switch (to) {
187	            case OPEN -> settings.refuseUnlessAllowed(sheetId, user, Permission.OPEN);
188	            case SETTLED -> settings.refuseUnlessAllowed(sheetId, user, Permission.SETTLE);
189	            case VOID -> settings.refuseUnlessAllowed(sheetId, user, Permission.VOID);
190	            default -> {
191	            }
192	        }
193	        if (to == ClaimStatus.PENDING || (to == ClaimStatus.SETTLED && claim.getStatus() == ClaimStatus.PENDING)
194	                || !claim.getStatus().canMoveTo(to)) {
195	            throw new ResponseStatusException(HttpStatus.CONFLICT,
196	                    "A " + claim.getStatus() + " claim cannot become " + to);
197	        }
198	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
199	            throw new ResponseStatusException(HttpStatus.CONFLICT,
200	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
201	        }
202	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
203	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
204	                    "The user who opened a claim cannot settle it");
205	        }
