207	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
208	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
209	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
210	        if (to == ClaimStatus.SETTLED) {
