318	    }
319	
320	    /** Refuse (422) settling or approving a claim at a due (null: n/a) above the proof threshold in
321	     *  force on its date while it has no proof. */
322	    private void refuseIfUnproven(Claim claim, BigDecimal due) {
323	        if (claim.getProofs() > 0 || due == null) {
324	            return;
325	        }
326	        BigDecimal threshold = sheets.proofThresholdOn(claim.getSheetId(), claim.getDate());
327	        if (threshold != null && due.compareTo(threshold) > 0) {
328	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
329	                    "A claim whose due is above the proof threshold needs a proof first");
330	        }
331	    }
332	
333	    /** A steward re-settles a SETTLED claim: its due is frozen again at the figure it would show
334	     *  today as an open claim bound by no statement (today's rates, grades, floor and late
335	     *  charge). Refused (404) when missing, (423) when dated in a closed period, (403) for anyone
336	     *  but a steward, and (409) unless SETTLED. */
337	    @Transactional
338	    public Claim resettle(String sheetId, String user, long id) {
339	        Claim claim = claims.findForUpdate(id, sheetId)
340	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
341	        refuseIfClosed(sheetId, claim.getDate());
342	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
343	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim");
344	        }
345	        if (claim.getStatus() != ClaimStatus.SETTLED) {
346	            throw new ResponseStatusException(HttpStatus.CONFLICT,
347	                    "Only a SETTLED claim is re-settled, not a " + claim.getStatus() + " one");
348	        }
349	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
350	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
351	        RollupService.Snapshot before = rollup.snapshot(sheetId);
352	        BigDecimal old = claim.getSettledDue();
353	        BigDecimal due = flooredOf(claim,
354	                LateCharge.of(sheets.find(sheetId)).addToOpen(claim, rateFigureOf(claim, person), roundingOf(claim)));
355	        claim.setSettledDue(due);
356	        claims.flush();
357	        logStatus(user, person, claim);
358	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(),
359	                " old=" + dueText(old) + " new=" + dueText(due));
360	        notifyWatchers(user, person, claim.getNumber());
361	        rollup.recordChanges(sheetId, user, before);
362	        return claim;
363	    }
364	
365	    /** A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by the
366	     *  person's last statement if that statement bound it. Refused (409) unless PENDING, (403) for
367	     *  a clerk, and (423) when it is dated in a closed period. */
368	    @Transactional
369	    public Claim reject(String sheetId, String user, long id, String reason) {
370	        Claim claim = pendingForSteward(sheetId, user, id);
371	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
372	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
373	        RollupService.Snapshot before = rollup.snapshot(sheetId);
374	        claim.setStatus(ClaimStatus.OPEN);
375	        claims.flush();
376	        logStatus(user, person, claim);
377	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), " reason=" + reason);
378	        rollup.recordChanges(sheetId, user, before);
379	        return claim;
380	    }
381	
382	    /** A steward (or a role the permission matrix lets reassign) moves a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its
383	     *  number and date, is listed as the new person's newest claim, and loses any figure a
384	     *  statement bound it to (live again until the new person's next statement). Refused (404)
385	     *  when the claim or person is missing, (423) when it is dated in a closed period, (403) for a
386	     *  role the sheet's permission matrix does not let reassign, (409) when SETTLED or VOID or already the person's, and (422) when it is dated after
387	     *  the new person's retirement date. */
388	    @Transactional
389	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
390	        Claim claim = claims.findForUpdate(id, sheetId)
391	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
392	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
393	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
394	        refuseIfClosed(sheetId, claim.getDate());
395	        settings.refuseUnlessAllowed(sheetId, user, Permission.REASSIGN);
396	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
397	            throw new ResponseStatusException(HttpStatus.CONFLICT,
398	                    "A " + claim.getStatus() + " claim cannot be reassigned");
399	        }
400	        if (claim.getPersonId() == toPersonId) {
401	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's");
402	        }
403	        refuseIfRetired(to, claim.getDate());
404	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
405	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
406	        RollupService.Snapshot before = rollup.snapshot(sheetId);
407	        claim.setPersonId(to.getId());
408	        claim.unbind();
409	        claim.setListed(claims.findLastListed(sheetId) + 1);
410	        claims.flush();
411	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(),
412	                " from=" + from.getName() + " to=" + to.getName());
413	        rollup.recordChanges(sheetId, user, before);
414	        return claim;
415	    }
416	
417	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and loses any
418	     *  figure a statement bound it to, and a new OPEN claim of the amount, with the same date and
419	     *  note, the next number, opened by the user, its due-by fixed now from the terms in force on
420	     *  the date (the person's own, else their grade's, else the sheet's), and naming the original's number as split-from, is listed as the person's newest.
421	     *  Refused (404) when missing, (423) when dated in a closed period, (403) for a role the
422	     *  sheet's permission matrix does not let open a claim, (409) unless OPEN and not deferred on
423	     *  the sheet's today, and (422) unless the amount is more than 0.00 and less than the claim's. */
424	    @Transactional
425	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
426	        Claim claim = claims.findForUpdate(id, sheetId)
427	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
428	        refuseIfClosed(sheetId, claim.getDate());
429	        settings.refuseUnlessAllowed(sheetId, user, Permission.OPEN);
430	        if (claim.getStatus() != ClaimStatus.OPEN) {
431	            throw new ResponseStatusException(HttpStatus.CONFLICT,
432	                    "Only an OPEN claim is split, not a " + claim.getStatus() + " one");
433	        }
434	        if (claim.isDeferredOn(sheets.today(sheetId))) {
435	            throw new ResponseStatusException(HttpStatus.CONFLICT,
436	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then");
437	        }
438	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
439	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
440	                    "The amount split off must be more than 0.00 and less than the claim's");
441	        }
442	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
443	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
444	        RollupService.Snapshot before = rollup.snapshot(sheetId);
445	        LocalDate on = claim.getDate();
446	        claim.setAmount(claim.getAmount().subtract(amount));
447	        claim.unbind();
448	        int terms = person.getTerms() != null ? person.getTerms()
449	                : sheets.find(sheetId).map(s -> s.termsFor(person.gradeOn(on), on)).orElse(Sheet.DEFAULT_TERMS);
450	        Claim fresh = new Claim(sheetId, person.getId(), amount, on, on.plusDays(terms), claim.getNote());
451	        fresh.setStatus(ClaimStatus.OPEN);
452	        fresh.setNumber(nextNumber(sheetId, on));
453	        fresh.setOpenedBy(user);
454	        fresh.setSplitFrom(claim.getNumber());
455	        fresh.setListed(claims.findLastListed(sheetId) + 1);
456	        Claim split = claims.saveAndFlush(fresh);
457	        logStatus(user, person, split);
458	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), " into=" + split.getNumber());
459	        record("CLAIM_OPENED", user, person, split);
460	        rollup.recordChanges(sheetId, user, before);
461	        return new Split(claim, split);
462	    }
463	
464	    /** The PENDING claim a steward decides on: refused (404) when missing, (423) when dated in a
465	     *  closed period, (409) unless PENDING, and (403) when the user is not a steward. */
466	    private Claim pendingForSteward(String sheetId, String user, long id) {
467	        Claim claim = claims.findForUpdate(id, sheetId)
468	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
469	        refuseIfClosed(sheetId, claim.getDate());
470	        if (claim.getStatus() != ClaimStatus.PENDING) {
471	            throw new ResponseStatusException(HttpStatus.CONFLICT,
472	                    "Only a PENDING claim is approved or rejected, not a " + claim.getStatus() + " one");
473	        }
474	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
475	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
476	                    "Only a steward approves or rejects a PENDING claim");
477	        }
478	        return claim;
479	    }
480	
481	    /** Write the claim's status now to its log: by the user, on the sheet's today, with the due
482	     *  it shows at this moment. */
483	    private void logStatus(String user, Person person, Claim claim) {
484	        BigDecimal due = shownDueOf(claim, person);
485	        log.save(new ClaimLog(claim.getSheetId(), claim.getId(), claim.getStatus(), user,
486	                sheets.today(claim.getSheetId()), due == null ? null : due.setScale(2, RoundingMode.HALF_EVEN)));
487	    }
488	
489	    private static String dueText(BigDecimal due) {
490	        return due == null ? "n/a" : due.toPlainString();
491	    }
492	
493	    /** Take a statement of a person: record their due-total now, and bind each of their claims
494	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold, nor a deferred one) to its figure now; the others
495	     *  are left unbound. */
496	    @Transactional
497	    public Statement statement(String sheetId, String user, long personId) {
498	        Person person = people.findForUpdate(personId, sheetId)
499	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
500	        LocalDate today = sheets.today(sheetId);
501	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
502	        RollupService.Snapshot before = rollup.snapshot(sheetId);
503	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person, today)).toList();
504	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
505	        for (Claim c : theirs) {
506	            if (counts(c, person, today)) {
507	                // the statement binds the figure; the late charge keeps following the sheet's today
508	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
509	            } else {
510	                c.unbind();
511	            }
512	        }
513	        claims.flush();
514	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
515	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
516	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
517	        rollup.recordChanges(sheetId, user, before);
518	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
519	    }
520	
521	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
522	     *  and the sheet's today on or after it) the next within the period containing the date
523	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
524	    private String nextNumber(String sheetId, LocalDate date) {
525	        if (!sheets.periodNumberingOn(sheetId)) {
526	            return String.valueOf(sheets.nextClaimNumber(sheetId));
527	        }
528	        // held until the transaction ends, so two claims opened at once are numbered one after the other
529	        sheets.lock(sheetId);
530	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
531	        int last = claims.findNumbers(sheetId).stream()
532	                .filter(n -> n.startsWith(prefix))
533	                .map(n -> n.substring(prefix.length()))
534	                .filter(n -> n.matches("\\d{1,9}"))
535	                .mapToInt(Integer::parseInt)
536	                .max().orElse(0);
537	        return prefix + (last + 1);
538	    }
539	
540	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
541	     *  the transaction ends so a period cannot be closed meanwhile. */
542	    private void refuseIfClosed(String sheetId, LocalDate date) {
543	        sheets.lock(sheetId);
544	        periods.refuseIfClosed(sheetId, date);
545	    }
546	
547	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
548	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
549	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
550	        if (amount.signum() >= 0) {
551	            return null;
552	        }
553	        if (corrects == null
554	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
555	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
556	                    "A negative amount must correct a settled claim of the same person");
557	        }
558	        return corrects;
559	    }
560	
561	    /** Refuse (422) a claim dated after its person's retirement date. */
562	    private static void refuseIfRetired(Person person, LocalDate date) {
563	        if (person.retiredBefore(date)) {
564	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
565	                    "The date is after the person's retirement date");
566	        }
567	    }
568	
569	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
570	     *  do, but not an open one dated within a hold of its person unless bound by a statement, nor
571	     *  one deferred on the sheet's today. */
572	    private static boolean counts(Claim c, Person person, LocalDate today) {
573	        return c.getStatus() == ClaimStatus.SETTLED
574	                || (c.getStatus().isOpen() && !c.isDeferredOn(today) && (c.isBound() || !person.heldOn(c.getDate())));
575	    }
576	
577	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
578	     *  charge on top, raised to the floor in force on its date. */
579	    private BigDecimal shownDueOf(Claim claim, Person person) {
580	        if (claim.getSettledDue() != null) {
581	            return claim.getSettledDue();
582	        }
583	        return flooredOf(claim,
584	                LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim)));
585	    }
586	
587	    /** A due (null: n/a, which stays n/a) raised to the sheet's floor in force on the claim's date; a
588	     *  correction's never is. */
589	    private BigDecimal flooredOf(Claim claim, BigDecimal due) {
590	        if (due == null || claim.isCorrection()) {
591	            return due;
592	        }
593	        return due.max(sheets.floorOn(claim.getSheetId(), claim.getDate()));
594	    }
595	
596	    /** A claim's figure before any late charge or floor: the one a statement bound it to (null: n/a),
597	     *  else (unbound, or PENDING) its rate figure. */
598	    private BigDecimal figureOf(Claim claim, Person person) {
599	        return claim.isBound() ? claim.getStatedDue() : rateFigureOf(claim, person);
600	    }
601	
602	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
603	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
604	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
605	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
606	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
607	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
608	            return null;
609	        }
610	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
611	    }
612	
613	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
614	     *  100, rounded as its rounding policy has it; null with no rate in force then. */
615	    private BigDecimal rateFigureOf(Claim claim, Person person) {
616	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
617	                .map(Rate::getPct)
618	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
619	                .orElse(null);
620	    }
621	
622	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
623	     *  correction the date of the claim it corrects. */
624	    private RoundingMode roundingOf(Claim claim) {
625	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
626	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
627	                        .map(Claim::getDate).orElse(claim.getDate());
628	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
629	    }
630	
631	    private void record(String event, String user, Person person, Claim claim) {
632	        record(event, user, person, claim, claim.getNumber());
633	    }
634	
635	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
636	    private void record(String event, String user, Person person, Claim claim, String number) {
637	        record(event, user, person, claim, number, "");
638	    }
639	
640	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
641	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
642	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
643	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
644	    }
645	
646	    /** Notify each user watching the person that one of their claims was settled, in the order
647	     *  they started watching. */
648	    private void notifyWatchers(String user, Person person, String number) {
649	        for (PersonWatch w : watches.findByPersonIdOrderByIdAsc(person.getId())) {
650	            audit.recordOnCommit("NOTIFY sheet=" + person.getSheetId() + " by=" + user + " user=" + w.getUserName()
651	                    + " person=" + person.getName() + " number=" + number);
652	        }
653	    }
654	
655	    private static String noteOf(String note) {
656	        return note == null ? "" : note.trim();
657	    }
658	}
